corrected_code:
namespace App\Livewire;

use Livewire\Component;
use App\Models\ExamAttempt;
use Illuminate\Support\Facades\Auth;

class ExamFeedbackComponent extends Component
{
    public int $attemptId;
    public string $graderFeedback = '';
    public int $scoreAdjustment = 0;

    public function saveFeedback()
    {
        $attempt = ExamAttempt::findOrFail($this->attemptId);
        $this->authorize('grade', $attempt);

        $attempt->update([
            'instructor_notes' => $this->graderFeedback,
            'bonus_points' => $this->scoreAdjustment
        ]);
    }

    public function render()
    {
        return view('livewire.exam-feedback');
    }
}
